:"Inanga at English Wikipedia","license":"Public domain","licenseUrl":null},{"slug":"yomari-katmandou","title":"Yomari de Katmandou (bouchées de riz fourrées à la mélasse et au sésame)","file":"File:Yomari.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Yomari.jpg/1280px-Yomari.jpg","page":"https://commons.wikimedia.org/wiki/File:Yomari.jpg","author":"Ritesh Man Tamrakar","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0"},{"slug":"zacusca","title":"Zacuscă roumaine (tartinade de poivrons et aubergines grillés)","file":"File:Zacuscă bgiu.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/6/6e/Zacusc%C4%83_bgiu.jpg","page":"https://commons.wikimedia.org/wiki/File:Zacusc%C4%83_bgiu.jpg","author":"No machine-readable author provided. Bogdan assumed (based on copyright claims).","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/"},{"slug":"zagorski-strukli","title":"Štrukli du Zagorje (pâte fine au fromage frais gratinée)","file":"File:Štrukli iz Okrugljaka.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/%C5%A0trukli_iz_Okrugljaka.jpg/1280px-%C5%A0trukli_iz_Okrugljaka.jpg","page":"https://commons.wikimedia.org/wiki/File:%C5%A0trukli_iz_Okrugljaka.jpg","author":"Bonč","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},{"slug":"zurcher-geschnetzeltes","title":"Émincé de veau à la zurichoise (sauce crème et champignons)","file":"File:Zürcher Geschnetzeltes at Zur rote Buech.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Z%C3%BCrcher_Geschnetzeltes_at_Zur_rote_Buech.jpg/1280px-Z%C3%BCrcher_Geschnetzeltes_at_Zur_rote_Buech.jpg","page":"https://commons.wikimedia.org/wiki/File:Z%C3%BCrcher_Geschnetzeltes_at_Zur_rote_Buech.jpg","author":"Jpatokal","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"},{"slug":"zurek-polonais","title":"Żurek polonais (soupe de seigle fermenté, saucisse et œuf)","file":"File:Żurek, Pologne.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/%C5%BBurek%2C_Pologne.jpg/1280px-%C5%BBurek%2C_Pologne.jpg","page":"https://commons.wikimedia.org/wiki/File:%C5%BBurek,_Pologne.jpg","author":"Mith","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}]$photos$::jsonb) as e
join public.recipes r on r.id = md5('spoontrotter:recipe:' || (e->>'slug'))::uuid;

delete from public.recipe_images i using spoontrotter_photos p where i.recipe_id = p.rid and i.source_type = 'external_licensed';

insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
  photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
select rid, 'external_licensed', 'ready', e->>'url', e->>'title', 'Wikimedia Commons', e->>'page',
  nullif(e->>'author', ''), e->>'license', nullif(e->>'licenseUrl', ''),
  'Photo : ' || coalesce(nullif(e->>'author', ''), 'auteur inconnu') || ' · ' || (e->>'license') || ' · Wikimedia Commons',
  true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.'
from spoontrotter_photos;

update public.recipes r set source_url = p.e->>'page', updated_at = now() from spoontrotter_photos p where r.id = p.rid;

drop table spoontrotter_photos;
